package com.bank.maintenance;

import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MergeIntervalsDemo {

    private static final Logger log = Logger.getLogger(MergeIntervalsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MaintenanceWindowMerger merger = new MaintenanceWindowMerger();

        // Windows as [start, end] minutes from midnight, out of order and overlapping.
        int[][] windows = {{60, 120}, {100, 150}, {200, 240}, {240, 300}};

        int[][] merged = merger.merge(windows);
        log.info(() -> "Coalesced outages: " + Arrays.deepToString(merged));
        // [[60,150],[200,300]]
    }
}

// ─── Would be in service/MaintenanceWindowMerger.java in a real project ───
class MaintenanceWindowMerger {

    private static final Logger log = Logger.getLogger(MaintenanceWindowMerger.class.getName());

    int[][] merge(int[][] intervals) {
        if (intervals.length == 0) return new int[0][];

        // Step 1: sort by start time so overlaps become local.
        java.util.Arrays.sort(intervals, java.util.Comparator.comparingInt(a -> a[0]));

        java.util.List<int[]> result = new java.util.ArrayList<>();
        int[] current = intervals[0].clone();

        for (int i = 1; i < intervals.length; i++) {
            int[] next = intervals[i];
            if (next[0] <= current[1]) {           // overlap or touch
                current[1] = Math.max(current[1], next[1]);  // extend (handles containment)
                final int s = current[0], e = current[1];
                log.fine(() -> "  merged → [" + s + "," + e + "]");
            } else {                               // gap → close current, start new
                result.add(current);
                current = next.clone();
            }
        }
        result.add(current);                       // push the final interval (do not forget!)
        return result.toArray(new int[0][]);
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
